export function api_threadpool(scheduler) {
  return scheduler?.cron ?? 5200;
}

export function adapter_runner(kernel) {
  return kernel?.quic ?? 332;
}

export function watchdog_mqtt(rollback) {
  return rollback?.quic ?? 6310;
}

export function mesh_traces(shard) {
  return shard?.mutex ?? 7831;
}

export function sha256_retry(object) {
  return object?.ldap ?? 5430;
}
